11	#include <pto/common/constants.hpp>
12	#include <pto/pto-inst.hpp>
13	
14	using namespace pto;
15	constexpr uint32_t BUFFER_NUM = 2;
16	constexpr uint32_t L0_PINGPONG_BYTES = 32 * 1024; // L0A/L0B ping-pong split (32 KiB per buffer)
17	
18	// Pipeline mental model (instruction-level):
19	// - TLOAD     (GM -> L1):   fill aMatTile/bMatTile
20	// - TEXTRACT  (L1 -> L0):   slice aMatTile/bMatTile into aTile/bTile for the current baseK
21	// - TMATMUL   (Cube):       cTile = A*B (accumulated over K)
22	// - TSTORE    (L0C -> GM):  write cTile back to GM
23	//
24	// The code still uses PIPE_MTE* events for synchronization because those are the underlying hardware pipes;
25	// comments refer to the high-level PTO instructions to make tuning easier.
26	
27	template <typename OutTile, typename LeftTile, typename RightTile>
28	AICORE inline void MatmulAcc(OutTile cTile, LeftTile aTile, RightTile bTile, uint32_t k)
29	{
30	    if (k == 0) {
31	        TMATMUL(cTile, aTile, bTile);
32	    } else {
33	        TMATMUL_ACC(cTile, cTile, aTile, bTile);
34	    }
35	}
36	
37	template <pipe_t srcPipe, pipe_t dstPipe>
38	AICORE inline void SetFlag(uint32_t id)
39	{
40	    set_flag(srcPipe, dstPipe, static_cast<event_t>(id));
41	}
42	template <pipe_t srcPipe, pipe_t dstPipe>
43	AICORE inline void WaitFlag(uint32_t id)
44	{
45	    wait_flag(srcPipe, dstPipe, static_cast<event_t>(id));
46	}
47	
48	template <
49	    typename T, typename U, typename S, int m, int k, int n, uint32_t singleCoreM, uint32_t singleCoreK,
50	    uint32_t singleCoreN>
51	AICORE inline void InitGMOffsets(
52	    __gm__ U*& currentSrc0, __gm__ S*& currentSrc1, __gm__ T*& currentDst, __gm__ T* out, __gm__ U* src0,
53	    __gm__ S* src1)
54	{
55	    // Work partition (SPMD-style):
56	    // - Each core owns a contiguous C tile of shape [singleCoreM, singleCoreN].
57	    // - It reads the corresponding A panel [singleCoreM, K] and B panel [K, singleCoreN].
58	    constexpr uint32_t mIter = m / singleCoreM;
59	    uint32_t mIterIdx = get_block_idx() % mIter; // get current launch core idx
60	    uint32_t nIterIdx = get_block_idx() / mIter;
61	    uint64_t gmOffsetA = mIterIdx * singleCoreM * k;
62	    uint64_t gmOffsetB = nIterIdx * k * singleCoreN;
63	    uint64_t gmOffsetC = mIterIdx * singleCoreM * n + nIterIdx * singleCoreN;
64	    currentSrc0 = src0 + gmOffsetA;
65	    currentSrc1 = src1 + gmOffsetB;
66	    currentDst = out + gmOffsetC;
67	}
68	
69	template <
70	    typename T, typename U, typename S, int m, int k, int n, uint32_t baseM, uint32_t baseK, uint32_t baseN,
71	    uint32_t stepKa, uint32_t stepKb, uint32_t singleCoreK, typename TileMatA, typename TileMatB, typename LeftTile,
72	    typename RightTile, typename ResTile>
73	AICORE inline void ProcessKIteration(
74	    uint32_t kIter, uint32_t i, uint32_t j, __gm__ U* currentSrc0, __gm__ S* currentSrc1, TileMatA aMatTile[BUFFER_NUM],
75	    TileMatB bMatTile[BUFFER_NUM], LeftTile aTile[BUFFER_NUM], RightTile bTile[BUFFER_NUM], ResTile& cTile,
76	    uint8_t& mte2DBFlag, uint8_t& mte1DBFlag)
77	{
78	    // A panel staged by each TLOAD (GM->L1) when kModstepKa == 0: [baseM, baseK * stepKa]
79	    using NDValidShapeA = TileShape2D<U, baseM, baseK * stepKa, Layout::ND>;
80	    using NDsingleCoreShapeA = BaseShape2D<U, m, k, Layout::ND>;
81	    using GlobalDataSrcA = GlobalTensor<U, NDValidShapeA, NDsingleCoreShapeA, Layout::ND>;
82	
83	    // B panel staged by each TLOAD (GM->L1) when kModstepKa == 0: [baseK * stepKb, baseN]
84	    using NDValidShapeB = TileShape2D<U, baseK * stepKb, baseN, Layout::DN>;
85	    using NDsingleCoreShapeB = BaseShape2D<U, k, n, Layout::DN>;
86	    using GlobalDataSrcB = GlobalTensor<U, NDValidShapeB, NDsingleCoreShapeB, Layout::DN>;
87	
88	    const uint32_t kModstepKa = kIter % stepKa;
89	
90	    // TLOAD stage:
91	    // - Every stepKa iterations, load a larger [baseM, baseK * stepKa] panel into L1 and then slice it with TEXTRACT.
92	    // - Double buffering is driven by mte2DBFlag.
93	    if (kModstepKa == 0) {
94	        GlobalDataSrcA gmA(currentSrc0 + i * singleCoreK * baseM + kIter * baseK);
95	        GlobalDataSrcB gmB(currentSrc1 + j * singleCoreK * baseN + kIter * baseK);
96	
97	        // Wait until TEXTRACT is done with this L1 buffer before reusing it.
98	        WaitFlag<PIPE_MTE1, PIPE_MTE2>(mte2DBFlag);
99	        TLOAD(aMatTile[mte2DBFlag], gmA);
100	        SetFlag<PIPE_MTE2, PIPE_MTE1>(0);
101	        TLOAD(bMatTile[mte2DBFlag], gmB);
102	        SetFlag<PIPE_MTE2, PIPE_MTE1>(1);
103	        mte2DBFlag = (mte2DBFlag == 0) ? 1 : 0;
104	    }
105	
106	    const uint32_t currMte2Idx = (mte2DBFlag == 0) ? 1 : 0; // mte2DBFlag reversed
107	    // Wait until TMATMUL is done with the current L0A/L0B buffer before overwriting it via TEXTRACT.
108	    WaitFlag<PIPE_M, PIPE_MTE1>(mte1DBFlag);
109	
110	    // TEXTRACT stage: slice the loaded L1 panel into the baseK chunk we need this iteration.
111	    if (kModstepKa == 0)
112	        WaitFlag<PIPE_MTE2, PIPE_MTE1>(0);
113	    TEXTRACT(aTile[mte1DBFlag], aMatTile[currMte2Idx], 0, kModstepKa * baseK);
114	
115	    if (kModstepKa == 0)
116	        WaitFlag<PIPE_MTE2, PIPE_MTE1>(1);
117	    TEXTRACT(bTile[mte1DBFlag], bMatTile[currMte2Idx], (kIter % stepKb) * baseK, 0);
118	
119	    if ((kIter + 1) % stepKa == 0) {
120	        // Allow the next TLOAD to reuse this L1 slot.
121	        SetFlag<PIPE_MTE1, PIPE_MTE2>(currMte2Idx);
122	    }
123	
124	    // TMATMUL stage: compute (or accumulate) into cTile.
125	    SetFlag<PIPE_MTE1, PIPE_M>(mte1DBFlag);
126	    WaitFlag<PIPE_MTE1, PIPE_M>(mte1DBFlag);
127	    MatmulAcc(cTile, aTile[mte1DBFlag], bTile[mte1DBFlag], kIter);
128	    // Signal that TMATMUL is done, so the next iteration may TEXTRACT into the other ping-pong slot.
129	    SetFlag<PIPE_M, PIPE_MTE1>(mte1DBFlag);
130	    mte1DBFlag = (mte1DBFlag == 0) ? 1 : 0;
131	}
132	
133	template <
134	    typename T, typename U, typename S, int m, int n, uint32_t baseM, uint32_t baseN, uint32_t singleCoreK,
135	    typename ResTile>
136	AICORE inline void StoreResult(ResTile& cTile, __gm__ T* currentDst, uint32_t i, uint32_t j)
137	{
138	    // TSTORE stage: write the finished C tile [baseM, baseN] back to GM.
139	    SetFlag<PIPE_M, PIPE_FIX>(0);
140	    WaitFlag<PIPE_M, PIPE_FIX>(0);
141	
142	    // the data size read from L0C after single k loop is [baseM, baseN]
143	    using NDValidShapeC = TileShape2D<T, baseM, baseN, Layout::ND>;
144	    using NDWholeShapeC = BaseShape2D<T, m, n, Layout::ND>; // stride use global C m n
145	    using GlobalDataOut = GlobalTensor<T, NDValidShapeC, NDWholeShapeC, Layout::ND>;
146	
147	    GlobalDataOut dstGlobal(currentDst + i * baseM * n + j * baseN);
148	    TSTORE(dstGlobal, cTile);
149	
150	    SetFlag<PIPE_FIX, PIPE_M>(0);
151	    WaitFlag<PIPE_FIX, PIPE_M>(0);
152	}
153	
154	AICORE inline void InitSyncFlags()
155	{
156	    SetFlag<PIPE_MTE1, PIPE_MTE2>(0);
157	    SetFlag<PIPE_MTE1, PIPE_MTE2>(1);
158	    SetFlag<PIPE_M, PIPE_MTE1>(0);
159	    SetFlag<PIPE_M, PIPE_MTE1>(1);
160	}
161	
162	AICORE inline void WaitSyncFlags()
163	{
164	    WaitFlag<PIPE_M, PIPE_MTE1>(0);
165	    WaitFlag<PIPE_M, PIPE_MTE1>(1);
166	    WaitFlag<PIPE_MTE1, PIPE_MTE2>(0);
167	    WaitFlag<PIPE_MTE1, PIPE_MTE2>(1);
168	}
169	
170	template <
171	    typename T, typename U, typename S, typename B, uint32_t blockDim, int m, int k, int n, int validM, int validK,
172	    int validN, uint32_t singleCoreM, uint32_t singleCoreK, uint32_t singleCoreN, uint32_t baseM, uint32_t baseK,
173	    uint32_t baseN, uint32_t stepM, uint32_t stepKa, uint32_t stepKb, uint32_t stepN>
174	AICORE inline void RunGemmE2E(__gm__ T* out, __gm__ U* src0, __gm__ S* src1)
175	{
176	    __gm__ U* currentSrc0 = nullptr;
177	    __gm__ S* currentSrc1 = nullptr;
178	    __gm__ T* currentDst = nullptr;
179	    InitGMOffsets<T, U, S, m, k, n, singleCoreM, singleCoreK, singleCoreN>(
180	        currentSrc0, currentSrc1, currentDst, out, src0, src1);
181	
182	    using TileMatA =
183	        Tile<TileType::Mat, U, baseM, baseK * stepKa, BLayout::ColMajor, baseM, baseK * stepKa, SLayout::RowMajor>;
184	    using TileMatB =
185	        Tile<TileType::Mat, S, baseK * stepKb, baseN, BLayout::RowMajor, baseK * stepKb, baseN, SLayout::ColMajor>;
186	
187	    TileMatA aMatTile[BUFFER_NUM];
188	    TileMatB bMatTile[BUFFER_NUM];
189	
190	    using LeftTile = TileLeft<U, baseM, baseK, baseM, baseK>;
191	    using RightTile = TileRight<S, baseK, baseN, baseK, baseN>;
192	    using ResTile = TileAcc<T, baseM, baseN, baseM, baseN>;
193	
194	    LeftTile aTile[BUFFER_NUM];
195	    RightTile bTile[BUFFER_NUM];
196	    ResTile cTile;
197	
198	    // L1 staging buffers (aMatTile/bMatTile) are double-buffered for TLOAD overlap.
199	    TASSIGN(aMatTile[0], 0x0);
200	    TASSIGN(aMatTile[1], 0x0 + baseM * baseK * stepKa * sizeof(U));
201	    TASSIGN(bMatTile[0], 0x0 + baseM * baseK * stepKa * BUFFER_NUM * sizeof(U));
202	    TASSIGN(bMatTile[1], 0x0 + baseM * baseK * stepKa * BUFFER_NUM * sizeof(U) + baseK * baseN * stepKb * sizeof(U));
203	
204	    // L0A/L0B ping-pong buffers (TEXTRACT destination).
205	    // Keep each per-buffer footprint <= 32 KiB to fit in a ping/pang slot.
206	    TASSIGN(aTile[0], 0x0);                     // L0A ping
207	    TASSIGN(aTile[1], 0x0 + L0_PINGPONG_BYTES); // L0A pang
208	    TASSIGN(bTile[0], 0x0);                     // L0B ping
209	    TASSIGN(bTile[1], 0x0 + L0_PINGPONG_BYTES); // L0B pang
210	    TASSIGN(cTile, 0x0);
211	
212	    constexpr uint32_t mLoop = singleCoreM / baseM;
213	    constexpr uint32_t nLoop = singleCoreN / baseN;
214	    constexpr uint32_t kLoop = singleCoreK / baseK;
215	    uint8_t mte2DBFlag = 0, mte1DBFlag = 0;
216	
217	    // supplement first sync instr for reverse sync in ProcessKIteration
218	    InitSyncFlags();
219	
220	    for (uint32_t i = 0; i < mLoop; i++) {
221	        for (uint32_t j = 0; j < nLoop; j++) {
222	            for (uint32_t kIter = 0; kIter < kLoop; kIter++) {
223	                ProcessKIteration<
224	                    T, U, S, m, k, n, baseM, baseK, baseN, stepKa, stepKb, singleCoreK, TileMatA, TileMatB, LeftTile,
225	                    RightTile, ResTile>(
226	                    kIter, i, j, currentSrc0, currentSrc1, aMatTile, bMatTile, aTile, bTile, cTile, mte2DBFlag,
227	                    mte1DBFlag);
228	            }
229	            StoreResult<T, U, S, m, n, baseM, baseN, singleCoreK, ResTile>(cTile, currentDst, i, j);
230	        }
231	    }
232	
233	    // supplement last sync instr for reverse sync in ProcessKIteration
234	    WaitSyncFlags();
235	}
236	
237	template <
238	    typename T, uint32_t blockDim, uint32_t m, uint32_t k, uint32_t n, uint32_t singleCoreM, uint32_t singleCoreK,
239	    uint32_t singleCoreN, uint32_t baseM, uint32_t baseK, uint32_t baseN, uint32_t stepM, uint32_t stepKa,
240	    uint32_t stepKb, uint32_t stepN>
241	__global__ AICORE void GemmPerformance(__gm__ uint8_t* out, __gm__ uint8_t* src0, __gm__ uint8_t* src1)
242	{
243	    RunGemmE2E<
244	        float, half, half, float, blockDim, m, k, n, m, k, n, singleCoreM, singleCoreK, singleCoreN, baseM, baseK,
245	        baseN, stepM, stepKa, stepKb, stepN>(
246	        reinterpret_cast<__gm__ float*>(out), reinterpret_cast<__gm__ half*>(src0),
247	        reinterpret_cast<__gm__ half*>(src1));
248	}
249	
250	#ifndef __COSTMODEL
251	template <typename T>
252	void LaunchGEMME2E(uint8_t* out, uint8_t* src0, uint8_t* src1, void* stream)
253	{
254	    constexpr uint32_t blockDim = 24;
255	    constexpr uint32_t m = 6144;
256	    constexpr uint32_t n = 6144;
257	    constexpr uint32_t k = 6144;
258	    constexpr uint32_t singleCoreM = 1536;
259	    constexpr uint32_t singleCoreN = 1024;
260	    constexpr uint32_t singleCoreK = 6144;
261	    constexpr uint32_t baseM = 128;
262	    constexpr uint32_t baseN = 256;
263	    constexpr uint32_t baseK = 64;
264	    constexpr uint32_t stepM = 1;
265	    constexpr uint32_t stepKa = 4;
266	    constexpr uint32_t stepKb = 4;
267	    constexpr uint32_t stepN = 1;
268	    GemmPerformance<
269	        T, blockDim, m, k, n, singleCoreM, singleCoreK, singleCoreN, baseM, baseK, baseN, stepM, stepKa, stepKb, stepN>
270	        <<<blockDim, nullptr, stream>>>(out, src0, src1);
271	}
272	
273	template void LaunchGEMME2E<uint16_t>(uint8_t* out, uint8_t* src0, uint8_t* src1, void* stream);
274	#endif
